// Authored audio fixtures for the audio oracle (ticket 6.4). Imports nothing from packages/core.
//
// Every byte is written from the public RIFF/WAVE and Standard MIDI File layouts and the length rule of
// docs/spec/engine/audio-media.md#audio-wav-midi-length (F4); the sample and note data are closed-form
// patterns, so there is nothing to copy from a legacy game and nothing to license (G6, G7). Each file
// carries a hand-worked length in ticks and the arithmetic that gives it; `checkAudioFiles` (index.mjs)
// parses the generated bytes with the independent reader in length.mjs and proves both agree.
//
// WAV length: `max(1, floor((120 * frames + rate) / (2 * rate)))`.
// MIDI length: with N the sum of delta ticks times tempo up to the last end-of-track (default tempo 500000
// before the first tempo event), `max(1, floor((12 * N + 100000 * d) / (200000 * d)))` for division d.

const concat = (parts) => {
  const out = [];
  for (const part of parts) for (const byte of part) out.push(byte);
  return out;
};
const ascii = (text) => [...text].map((c) => c.charCodeAt(0));
const le16 = (n) => [n & 0xff, (n >> 8) & 0xff];
const le32 = (n) => [n & 0xff, (n >> 8) & 0xff, (n >> 16) & 0xff, (n >>> 24) & 0xff];
const be16 = (n) => [(n >> 8) & 0xff, n & 0xff];
const be32 = (n) => [(n >>> 24) & 0xff, (n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff];

// ---------------------------------------------------------------------------------------------
// WAV

const chunk = (id, body) => [...ascii(id), ...le32(body.length), ...body, ...(body.length & 1 ? [0] : [])];
const riff = (chunks) => {
  const body = concat([ascii("WAVE"), ...chunks]);
  return Uint8Array.from([...ascii("RIFF"), ...le32(body.length), ...body]);
};

const pcmFmt = (channels, rate, bits) => {
  const align = (channels * bits) / 8;
  return chunk("fmt ", [...le16(1), ...le16(channels), ...le32(rate), ...le32(rate * align), ...le16(align), ...le16(bits)]);
};

const pcm8Data = (count) => Array.from({ length: count }, (_, i) => 128 + ((i * 5) % 64) - 32);
const pcm16Data = (count) => concat(Array.from({ length: count }, (_, i) => le16((((i * 97) % 4001) - 2000) & 0xffff)));

// The seven standard MS-ADPCM coefficient pairs (public format constants).
const MS_COEFFICIENTS = [[256, 0], [512, -256], [0, 0], [192, 64], [240, 0], [460, -208], [392, -232]];

function msAdpcm({ blocks, fact }) {
  const rate = 8000;
  const blockAlign = 256;
  const perBlock = (blockAlign - 7) * 2 + 2; // 500
  const fmt = chunk("fmt ", [
    ...le16(2), ...le16(1), ...le32(rate), ...le32(Math.floor((rate * blockAlign) / perBlock)), ...le16(blockAlign), ...le16(4),
    ...le16(32), ...le16(perBlock), ...le16(7),
    ...concat(MS_COEFFICIENTS.map(([a, b]) => [...le16(a & 0xffff), ...le16(b & 0xffff)])),
  ]);
  const data = [];
  for (let b = 0; b < blocks; b += 1) {
    data.push(b % 7, ...le16(16), ...le16(0), ...le16(0));
    for (let i = 0; i < blockAlign - 7; i += 1) data.push((i * 37 + b * 11) & 0xff);
  }
  const chunks = [fmt];
  if (fact !== null) chunks.push(chunk("fact", le32(fact)));
  chunks.push(chunk("data", data));
  return riff(chunks);
}

function imaAdpcm({ channels, blocks, fact }) {
  const rate = 8000;
  const blockAlign = channels === 1 ? 256 : 512;
  const perBlock = ((blockAlign - 4 * channels) * 8) / (4 * channels) + 1; // 505 for both layouts
  const fmt = chunk("fmt ", [
    ...le16(0x11), ...le16(channels), ...le32(rate), ...le32(Math.floor((rate * blockAlign) / perBlock)), ...le16(blockAlign), ...le16(4),
    ...le16(2), ...le16(perBlock),
  ]);
  const data = [];
  for (let b = 0; b < blocks; b += 1) {
    for (let c = 0; c < channels; c += 1) data.push(...le16(0), (b * 3 + c) % 89, 0);
    const groups = (blockAlign - 4 * channels) / (4 * channels);
    for (let g = 0; g < groups; g += 1) for (let c = 0; c < channels; c += 1) for (let i = 0; i < 4; i += 1) data.push((g * 29 + i * 7 + c * 3 + b) & 0xff);
  }
  const chunks = [fmt];
  if (fact !== null) chunks.push(chunk("fact", le32(fact)));
  chunks.push(chunk("data", data));
  return riff(chunks);
}

const listInfo = chunk("LIST", [...ascii("INFO"), ...chunk("ISFT", ascii("tkr"))]);

// ---------------------------------------------------------------------------------------------
// MIDI

const vlq = (n) => {
  const groups = [n & 0x7f];
  let rest = n >> 7;
  while (rest > 0) {
    groups.unshift((rest & 0x7f) | 0x80);
    rest >>= 7;
  }
  return groups;
};
const ev = (delta, ...bytes) => [...vlq(delta), ...bytes];
const meta = (delta, type, body) => ev(delta, 0xff, type, ...vlq(body.length), ...body);
const eot = (delta) => meta(delta, 0x2f, []);
const tempo = (delta, micros) => meta(delta, 0x51, [(micros >> 16) & 0xff, (micros >> 8) & 0xff, micros & 0xff]);
const trackName = (delta, text) => meta(delta, 0x03, ascii(text));
const sysex = (delta, ...body) => ev(delta, 0xf0, ...vlq(body.length), ...body);
const noteOn = (delta, note, velocity) => ev(delta, 0x90, note, velocity);
const noteOff = (delta, note, velocity) => ev(delta, 0x80, note, velocity);
const program = (delta, number) => ev(delta, 0xc0, number);
const controller = (delta, number, value) => ev(delta, 0xb0, number, value);

const mtrk = (events) => {
  const body = concat(events);
  return [...ascii("MTrk"), ...be32(body.length), ...body];
};
const smf = (type, division, tracks) => Uint8Array.from([...ascii("MThd"), ...be32(6), ...be16(type), ...be16(tracks.length), ...be16(division), ...concat(tracks.map(mtrk))]);

// ---------------------------------------------------------------------------------------------
// The files. `lengthTicks` and `workings` are written by hand from the rule above; nothing here
// computes them from the bytes.

const wavEntry = (name, bytes, o) => ({ name, kind: "wav", bytes, ...o });
const midiEntry = (name, bytes, o) => ({ name, kind: "midi", bytes, ...o });

export const AUDIO_FILES = [
  wavEntry("pcm8-mono-8000.wav", riff([pcmFmt(1, 8000, 8), listInfo, chunk("data", pcm8Data(4000))]), {
    codec: "pcm8", channels: 1, rate: 8000, frames: 4000, lengthTicks: 30,
    workings: "4000 frames at 8000 Hz is 0.5 s; (120 x 4000 + 8000) / 16000 = 30.5, floor 30. A LIST/INFO chunk with an odd-sized ISFT item precedes the data.",
  }),
  wavEntry("pcm16-mono-8000.wav", riff([pcmFmt(1, 8000, 16), chunk("data", pcm16Data(2000))]), {
    codec: "pcm16", channels: 1, rate: 8000, frames: 2000, lengthTicks: 15,
    workings: "4000 data bytes / block align 2 = 2000 frames; (120 x 2000 + 8000) / 16000 = 15.5, floor 15.",
  }),
  wavEntry("pcm16-stereo-8000.wav", riff([pcmFmt(2, 8000, 16), chunk("data", pcm16Data(800))]), {
    codec: "pcm16", channels: 2, rate: 8000, frames: 400, lengthTicks: 3,
    workings: "1600 data bytes / block align 4 = 400 frames; (120 x 400 + 8000) / 16000 = 3.5, floor 3.",
  }),
  wavEntry("pcm8-half-tick.wav", riff([pcmFmt(1, 8000, 8), chunk("data", pcm8Data(200))]), {
    codec: "pcm8", channels: 1, rate: 8000, frames: 200, lengthTicks: 2,
    workings: "200 frames at 8000 Hz is exactly 1.5 ticks; (120 x 200 + 8000) / 16000 = 2.0, so a half tick rounds up to 2.",
  }),
  wavEntry("pcm8-min-one-tick.wav", riff([pcmFmt(1, 8000, 8), chunk("data", pcm8Data(1))]), {
    codec: "pcm8", channels: 1, rate: 8000, frames: 1, lengthTicks: 1,
    workings: "one frame; (120 + 8000) / 16000 = 0.5075, floor 0, raised to the minimum of 1. The odd data chunk is padded.",
  }),
  wavEntry("msadpcm-mono-8000.wav", msAdpcm({ blocks: 4, fact: null }), {
    codec: "ms-adpcm", channels: 1, rate: 8000, frames: 2000, lengthTicks: 15,
    workings: "block align 256 holds (256 - 7) x 2 + 2 = 500 samples; 4 blocks and no fact chunk = 2000 frames; (120 x 2000 + 8000) / 16000 = 15.5, floor 15.",
  }),
  wavEntry("msadpcm-mono-8000-fact.wav", msAdpcm({ blocks: 4, fact: 1900 }), {
    codec: "ms-adpcm", channels: 1, rate: 8000, frames: 1900, lengthTicks: 14,
    workings: "the same four 500-sample blocks, but the fact chunk says 1900 frames and wins; (120 x 1900 + 8000) / 16000 = 14.75, floor 14.",
  }),
  wavEntry("ima-adpcm-mono-8000.wav", imaAdpcm({ channels: 1, blocks: 4, fact: 2020 }), {
    codec: "ima-adpcm", channels: 1, rate: 8000, frames: 2020, lengthTicks: 15,
    workings: "block align 256 holds (256 - 4) x 2 + 1 = 505 samples; 4 blocks = 2020 frames (fact 2020); (120 x 2020 + 8000) / 16000 = 15.65, floor 15.",
  }),
  wavEntry("ima-adpcm-stereo-8000.wav", imaAdpcm({ channels: 2, blocks: 2, fact: null }), {
    codec: "ima-adpcm", channels: 2, rate: 8000, frames: 1010, lengthTicks: 8,
    workings: "stereo block align 512 is two 4-byte channel headers then 63 groups of 8 bytes (4 per channel): 504 samples per channel plus the header sample = 505 frames per block; 2 blocks and no fact chunk = 1010 frames; (120 x 1010 + 8000) / 16000 = 8.075, floor 8.",
  }),
  midiEntry("midi0-480-default-tempo.mid", smf(0, 480, [[
    trackName(0, "default"), program(0, 0), noteOn(0, 60, 100), noteOff(960, 60, 64), noteOn(0, 62, 100),
    [...vlq(480), 62, 0], // running status: a note-on with velocity 0 ends the note
    eot(480),
  ]]), {
    type: 0, division: 480, lengthTicks: 120, bank: { dialect: "gm", bankSelect: false },
    workings: "events at 0, 960, 960, 1440 and end-of-track at 1920; no tempo event, so N = 1920 x 500000 = 960000000; (12 x 960000000 + 100000 x 480) / (200000 x 480) = 120.5, floor 120 (2 s).",
  }),
  midiEntry("midi0-96-tempo-change.mid", smf(0, 96, [[
    sysex(0, 0x7e, 0x7f, 0x09, 0x01, 0xf7), noteOn(0, 60, 100), tempo(96, 250000), noteOff(96, 60, 64), eot(96),
  ]]), {
    type: 0, division: 96, lengthTicks: 60, bank: { dialect: "gm", bankSelect: false },
    workings: "a GM System On sysex, then 96 ticks at the default 500000, a tempo change to 250000 at tick 96, then 192 ticks at 250000 to the end at 288; N = 96 x 500000 + 192 x 250000 = 96000000; (12 x 96000000 + 100000 x 96) / (200000 x 96) = 60.5, floor 60 (1 s).",
  }),
  midiEntry("midi1-240-tempo-map.mid", smf(1, 240, [
    [trackName(0, "tempo"), tempo(120, 400000), tempo(240, 1000000), eot(120)],
    [trackName(0, "lead"), program(0, 5), noteOn(0, 64, 80), noteOff(720, 64, 0), eot(0)],
  ]), {
    type: 1, division: 240, lengthTicks: 129, bank: { dialect: "gm", bankSelect: false },
    workings: "two tracks merged by absolute tick: default 500000 for ticks 0-120, 400000 for 120-360 (tempo track), 1000000 for 360-720; the note track ends last at 720, so the tempo carries on past its own end at 480. N = 120 x 500000 + 240 x 400000 + 360 x 1000000 = 516000000; (12 x 516000000 + 100000 x 240) / (200000 x 240) = 129.5, floor 129 (2.15 s).",
  }),
  midiEntry("midi0-480-round-up.mid", smf(0, 480, [[trackName(0, "round"), noteOn(0, 60, 100), eot(1900)]]), {
    type: 0, division: 480, lengthTicks: 119, bank: { dialect: "gm", bankSelect: false },
    workings: "end at 1900; N = 1900 x 500000 = 950000000 = 1.9792 s = 118.75 ticks; (12 x 950000000 + 100000 x 480) / (200000 x 480) = 119.25, floor 119 (rounds up).",
  }),
  midiEntry("midi1-480-tempo-only.mid", smf(1, 480, [[tempo(480, 250000), eot(480)], [eot(0)]]), {
    type: 1, division: 480, lengthTicks: 45, bank: { dialect: "gm", bankSelect: false },
    workings: "no note events: the tempo map alone gives the length. 480 ticks at 500000 then 480 at 250000; N = 360000000 = 0.75 s; (12 x 360000000 + 100000 x 480) / (200000 x 480) = 45.5, floor 45.",
  }),
  midiEntry("midi0-empty-minimum.mid", smf(0, 480, [[eot(0)]]), {
    type: 0, division: 480, lengthTicks: 1, bank: { dialect: "gm", bankSelect: false },
    workings: "only an end-of-track at tick 0; N = 0; (0 + 100000 x 480) / (200000 x 480) = 0.5, floor 0, raised to the minimum of 1.",
  }),
  midiEntry("midi0-xg-bank-select.mid", smf(0, 480, [[
    sysex(0, 0x43, 0x10, 0x4c, 0x00, 0x00, 0x7e, 0x00, 0xf7), controller(0, 0, 1), program(0, 5), noteOn(0, 60, 100), noteOff(480, 60, 64), eot(0),
  ]]), {
    type: 0, division: 480, lengthTicks: 30, bank: { dialect: "xg", bankSelect: true },
    workings: "an XG System On sysex (manufacturer 43, model 4C) and controller 0 set to 1; ends at 480; N = 240000000 = 0.5 s; (12 x 240000000 + 100000 x 480) / (200000 x 480) = 30.5, floor 30. Dialect xg, bank select true.",
  }),
  midiEntry("midi0-gs-reset.mid", smf(0, 96, [[
    sysex(0, 0x41, 0x10, 0x42, 0x12, 0x40, 0x00, 0x7f, 0x00, 0x41, 0xf7), noteOn(0, 60, 100), noteOff(96, 60, 64), eot(0),
  ]]), {
    type: 0, division: 96, lengthTicks: 30, bank: { dialect: "gs", bankSelect: false },
    workings: "a GS Reset sysex (manufacturer 41, model 42), no bank select; ends at 96; N = 48000000 = 0.5 s; (12 x 48000000 + 100000 x 96) / (200000 x 96) = 30.5, floor 30. Dialect gs, bank select false.",
  }),
];

/** The hand-worked length of an authored file, for the scenes that play one. */
export const authoredLength = (name) => {
  const entry = AUDIO_FILES.find((f) => f.name === name);
  if (entry === undefined) throw new Error(`no authored audio file ${name}`);
  return entry.lengthTicks;
};
